<style>
  body {
    background: #b3b3b3;
    font-family: Georgia, 'Times New Roman', serif;
    margin: 0;
    padding: 0;
    position: relative;
  }
  .page {
    max-width: 1650px;
    margin: 0 auto;
    padding: 40px 60px 80px 60px;
    position: relative;
    min-height: 2000px;
  }
  .crop-note {
    font-family: 'Courier New', monospace;
    font-size: 13px;
    color: #333;
    border-bottom: 1px solid #333;
    padding-bottom: 4px;
