    letter-spacing: 1px;
  }
  .header-row {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    border-bottom: 4px solid #1a1a1a;
    margin-bottom: 30px;
    position: relative;
  }
  .header-rule {
    flex: 1;
    height: 4px;
    background: #1a1a1a;
    margin-bottom: 8px;
  }
  .parody-logo {
    font-family: 'Brush Script MT', cursive;
